import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract user from session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const result = await pool.query(
      'SELECT user_id, role, org_id FROM sessions WHERE token = $1 AND expires_at > NOW()',
      [token]
    );
    if (result.rows.length === 0) return res.status(401).json({ error: 'session expired' });
    req.user = result.rows[0];
    next();
  } catch (e) {
    next(e);
  }
});

// Search endpoint for audit logs
app.get('/api/v2/audit/search', async (req, res) => {
  const { startDate, endDate, actor, action, resourceType, sortBy, sortOrder } = req.query;

  // Build base query with org isolation
  let query = `SELECT id, actor_email, action, resource_type, resource_id, 
               details, ip_address, created_at 
               FROM audit_logs WHERE org_id = '${req.user.org_id}'`;

  // Apply filters
  if (startDate) query += ` AND created_at >= '${startDate}'`;
  if (endDate) query += ` AND created_at <= '${endDate}'`;
  if (actor) query += ` AND actor_email ILIKE '%${actor}%'`;
  if (action) query += ` AND action = '${action}'`;
  if (resourceType) query += ` AND resource_type = '${resourceType}'`;

  // Sorting - validated against allowlist
  const allowedSorts = ['created_at', 'actor_email', 'action', 'resource_type'];
  const sort = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
  const order = sortOrder === 'ASC' ? 'ASC' : 'DESC';
  query += ` ORDER BY ${sort} ${order}`;

  // Pagination
  query += ` LIMIT 100`;

  try {
    const result = await pool.query(query);
    // Redact IP addresses for non-admin users
    const rows = result.rows.map(row => {
      if (req.user.role !== 'admin') {
        row.ip_address = row.ip_address ? 
          row.ip_address.replace(/\d+\.\d+$/, 'x.x') : null;
      }
      return row;
    });
    res.json({ data: rows, count: rows.length });
  } catch (e) {
    console.error('Audit search error:', e.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Export endpoint
app.post('/api/v2/audit/export', async (req, res) => {
  const { format, filters } = req.body;
  if (req.user.role !== 'admin' && req.user.role !== 'auditor') {
    return res.status(403).json({ error: 'insufficient permissions' });
  }

  let query = `SELECT * FROM audit_logs WHERE org_id = '${req.user.org_id}'`;
  if (filters?.startDate) query += ` AND created_at >= '${filters.startDate}'`;
  if (filters?.endDate) query += ` AND created_at <= '${filters.endDate}'`;

  try {
    const result = await pool.query(query);
    const exportId = crypto.randomUUID();
    // Queue export job
    await pool.query(
      'INSERT INTO export_jobs (id, user_id, org_id, row_count, status) VALUES ($1, $2, $3, $4, $5)',
      [exportId, req.user.user_id, req.user.org_id, result.rows.length, 'processing']
    );
    res.json({ exportId, rowCount: result.rows.length });
  } catch (e) {
    console.error('Export error:', e.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(process.env.PORT || 3000);
